import 'package:flutter/material.dart';

const bg = Color(0xFFF7FAF7);
const green = Color(0xFF2E9E4F);
const gold = Color(0xFFD6AD45);
const text = Color(0xFF172019);
const muted = Color(0xFF667066);
const surface = Colors.white;
const border = Color(0xFFDCE5DC);

void main() => runApp(const FarmPlugApp());
void push(BuildContext context, Widget page) => Navigator.of(context).push(MaterialPageRoute(builder: (_) => page));
void home(BuildContext context) => Navigator.of(context).pushAndRemoveUntil(MaterialPageRoute(builder: (_) => const HomeShell()), (r) => false);

class FarmPlugApp extends StatelessWidget {
  const FarmPlugApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'FarmPlug AI',
    theme: ThemeData(useMaterial3: true, brightness: Brightness.light, scaffoldBackgroundColor: bg, colorScheme: ColorScheme.fromSeed(seedColor: green, brightness: Brightness.light), appBarTheme: const AppBarTheme(backgroundColor: bg, foregroundColor: text, elevation: 0), cardTheme: const CardThemeData(color: surface, elevation: 0), inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: surface, border: OutlineInputBorder(borderRadius: BorderRadius.all(Radius.circular(14)), borderSide: BorderSide(color: border)), enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.all(Radius.circular(14)), borderSide: BorderSide(color: border)), focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.all(Radius.circular(14)), borderSide: BorderSide(color: green, width: 1.5)))),
    home: const SplashPage(),
  );
}

class SplashPage extends StatefulWidget { const SplashPage({super.key}); @override State<SplashPage> createState() => _SplashState(); }
class _SplashState extends State<SplashPage> { @override void initState(){super.initState();Future.delayed(const Duration(milliseconds:500),go);} void go(){if(!mounted)return;Navigator.of(context).pushReplacement(MaterialPageRoute(builder:(_)=>const WelcomePage()));} @override Widget build(BuildContext context)=>const Scaffold(body:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.eco,color:green,size:64),SizedBox(height:12),Text('FarmPlug AI',style:TextStyle(color:text,fontSize:30,fontWeight:FontWeight.w800)),SizedBox(height:8),Text('Smart farming. Better decisions. Greater yields.',textAlign:TextAlign.center,style:TextStyle(color:muted)),SizedBox(height:20),CircularProgressIndicator(color:green)]))); }
class Frame extends StatelessWidget { final String title; final String subtitle; final List<Widget> children; const Frame({super.key,required this.title,required this.subtitle,required this.children}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(title,style:const TextStyle(fontWeight:FontWeight.w800)),leading:Navigator.canPop(context)?const BackButton():null),body:SafeArea(child:ListView(padding:const EdgeInsets.fromLTRB(20,12,20,28),keyboardDismissBehavior:ScrollViewKeyboardDismissBehavior.onDrag,children:[Text(subtitle,style:const TextStyle(color:muted)),const SizedBox(height:18),...children.map((w)=>Padding(padding:const EdgeInsets.only(bottom:14),child:w))]))); }
Widget primary(String label,VoidCallback onTap)=>SizedBox(width:double.infinity,height:52,child:FilledButton(onPressed:onTap,style:FilledButton.styleFrom(backgroundColor:green,foregroundColor:Colors.white,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14))),child:Text(label,style:const TextStyle(fontWeight:FontWeight.w700))));
Widget outline(String label,VoidCallback onTap)=>SizedBox(width:double.infinity,height:50,child:OutlinedButton(onPressed:onTap,style:OutlinedButton.styleFrom(foregroundColor:green,side:const BorderSide(color:green),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14))),child:Text(label,style:const TextStyle(fontWeight:FontWeight.w700))));
Widget input(String label,IconData icon,{TextEditingController? controller,bool obscure=false,TextInputType? type,String? Function(String?)? validator})=>TextFormField(controller:controller,obscureText:obscure,keyboardType:type,validator:validator,decoration:InputDecoration(labelText:label,prefixIcon:Icon(icon)));
Widget cardLink(BuildContext context,String title,String detail,IconData icon,Widget page,{Color color=green})=>Card(child:ListTile(onTap:()=>push(context,page),leading:CircleAvatar(backgroundColor:color.withAlpha(25),foregroundColor:color,child:Icon(icon)),title:Text(title,style:const TextStyle(color:text,fontWeight:FontWeight.w700)),subtitle:Text(detail,style:const TextStyle(color:muted)),trailing:const Icon(Icons.chevron_right,color:muted)));
