class _SignInState extends State<SignInPage> { final form=GlobalKey<FormState>(); final login=TextEditingController(); final pass=TextEditingController(); @override void dispose(){login.dispose();pass.dispose();super.dispose();} @override Widget build(BuildContext context)=>Frame(title:'Sign In',subtitle:'Use your FarmPlug account.',children:[Form(key:form,child:Column(children:[input('Phone or email',Icons.person,controller:login,validator:(v)=>v==null||v.trim().isEmpty?'Enter phone or email':null),const SizedBox(height:12),input('Password',Icons.lock,controller:pass,obscure:true,validator:(v)=>v==null||v.length<6?'Minimum 6 characters':null)])),TextButton(onPressed:()=>push(context,const ForgotPage()),child:const Text('Forgot password?')),primary('Sign In',(){if(form.currentState!.validate())home(context);}),outline('Continue with Google',()=>push(context,const GooglePage())),TextButton(onPressed:()=>push(context,const SignUpPage()),child:const Text('New to FarmPlug? Sign Up'))]); }
