class _SignUpState extends State<SignUpPage> { final form=GlobalKey<FormState>(); final name=TextEditingController(); final phone=TextEditingController(); final pass=TextEditingController(); final confirm=TextEditingController(); @override void dispose(){name.dispose();phone.dispose();pass.dispose();confirm.dispose();super.dispose();} @override Widget build(BuildContext context)=>Frame(title:'Create Account',subtitle:'Create your farmer workspace.',children:[Form(key:form,child:Column(children:[input('Full name',Icons.person,controller:name,validator:(v)=>v==null||v.trim().isEmpty?'Enter your name':null),const SizedBox(height:12),input('Phone number',Icons.phone,controller:phone,type:TextInputType.phone,validator:(v)=>v==null||v.trim().length<10?'Enter valid phone':null),const SizedBox(height:12),input('Password',Icons.lock,controller:pass,obscure:true,validator:(v)=>v==null||v.length<6?'Minimum 6 characters':null),const SizedBox(height:12),input('Confirm password',Icons.lock_reset,controller:confirm,obscure:true,validator:(v){if(v==null||v.isEmpty)return'Confirm your password';if(v!=pass.text)return'Passwords do not match';return null;})])),primary('Create Account',(){if(form.currentState!.validate())home(context);})]); }
